#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"; source "${SCRIPT_DIR}/lib/common.sh"; source "${SCRIPT_DIR}/lib/config.sh"; source "${SCRIPT_DIR}/lib/pmtiles.sh"; source "${SCRIPT_DIR}/lib/overview.sh"
OVERVIEW=""; for arg in "$@"; do case "${arg}" in --overview=*) OVERVIEW="${arg#*=}";; --yyyymmdd=*) YYYYMMDD="${arg#*=}";; --workdir=*) WORKDIR="${arg#*=}";; -h|--help) printf 'usage: %s --overview=<id> [--yyyymmdd=YYYYMMDD] [--workdir=<path>]\n' "$0"; exit 0;; *) die "${HUAVD_EXIT_INPUT}" "unknown argument: ${arg}";; esac; done
[[ -n "${OVERVIEW}" ]] || die "${HUAVD_EXIT_INPUT}" "--overview is required"; validate_yyyymmdd "${YYYYMMDD}"; require_cmd jq sha512sum stat pmtiles; overview_validate "${OVERVIEW}"
pmtiles="$(overview_pmtiles_path "${OVERVIEW}" "${YYYYMMDD}")"; manifest="$(overview_manifest_path "${OVERVIEW}" "${YYYYMMDD}")"; require_file "${pmtiles}"; require_file "${manifest}"; require_file "$(overview_sha512_path "${OVERVIEW}" "${YYYYMMDD}")"
failures=0; check() { [[ "$2" == "$3" ]] && printf 'OK   %s\n' "$1" || { printf 'FAIL %s: expected %s got %s\n' "$1" "$3" "$2"; failures=$((failures+1)); }; }
check magic "$(pmtiles_magic "${pmtiles}")" PMTiles; check spec_version "$(pmtiles_spec_version "${pmtiles}")" 3; check tile_type "$(pmtiles_tile_type "${pmtiles}")" 1; check internal_compression "$(pmtiles_internal_compression "${pmtiles}")" 2; check tile_compression "$(pmtiles_tile_compression "${pmtiles}")" 2; [[ "$(pmtiles_max_zoom "${pmtiles}")" -le 10 ]] || { printf 'FAIL max zoom > 10\n'; failures=$((failures+1)); }
metadata="$(pmtiles_cli_metadata "${pmtiles}")"; expected="$(overview_layers_json "${OVERVIEW}")"; actual="$(jq -c '[.vector_layers[].id] | sort' <<< "${metadata}")"; check metadata_layers "${actual}" "$(jq -c 'sort' <<< "${expected}")"; check metadata_asset_role "$(jq -r '."huavd:asset-role"' <<< "${metadata}")" overview-vector; check manifest_asset_role "$(jq -r '.huavd_record.asset_role' "${manifest}")" overview-vector; check manifest_source_type "$(jq -r '.huavd_record.source_type' "${manifest}")" osm-pbf; check manifest_size "$(jq -r .output.size_bytes "${manifest}")" "$(stat -c %s "${pmtiles}")"; check manifest_sha "$(jq -r .output.sha512 "${manifest}")" "$(sha512_value "${pmtiles}")"; check sidecar_sha "$(awk '{print $1}' "$(overview_sha512_path "${OVERVIEW}" "${YYYYMMDD}")")" "$(sha512_value "${pmtiles}")"
metadata="$(pmtiles_cli_metadata "${pmtiles}")"; expected="$(overview_layers_json "${OVERVIEW}")"; actual="$(jq -c '[.vector_layers[].id] | sort' <<< "${metadata}")"; check metadata_layers "${actual}" "$(jq -c 'sort' <<< "${expected}")"; check metadata_asset_role "$(jq -r '."huavd:asset-role"' <<< "${metadata}")" overview-vector; check manifest_asset_role "$(jq -r '.huavd_record.asset_role' "${manifest}")" overview-vector; check manifest_source_type "$(jq -r '.huavd_record.source_type' "${manifest}")" osm-pbf; check manifest_size "$(jq -r .output.size_bytes "${manifest}")" "$(stat -c %s "${pmtiles}")"; check manifest_sha "$(jq -r .output.sha512 "${manifest}")" "$(sha512_value "${pmtiles}")"; check sidecar_sha "$(awk '{print $1}' "$(overview_sha512_path "${OVERVIEW}" "${YYYYMMDD}")")" "$(sha512_value "${pmtiles}")"; jq -n -e --argjson header "$(pmtiles_bounds "${pmtiles}")" --argjson metadata "$(jq -c .bounds <<< "${metadata}")" '[0,1,2,3] | all((($header[.] - $metadata[.]) | if . < 0 then -. else . end) <= 0.0000001)' >/dev/null || { printf 'FAIL metadata bounds\n'; failures=$((failures+1)); }
while IFS= read -r layer; do fields="$(layer_final_fields_json "${layer}")"; jq -e --arg layer "${layer}" --argjson fields "${fields}" '.vector_layers[] | select(.id == $layer) | .fields == $fields' <<< "${metadata}" >/dev/null || { printf 'FAIL metadata fields for %s\n' "${layer}"; failures=$((failures+1)); }; done < <(overview_layers "${OVERVIEW}")
jq -e '.source.composition.method == "osmium-merge" and (.source.composition.inputs | length > 0)' "${manifest}" >/dev/null || { printf 'FAIL manifest composition\n'; failures=$((failures+1)); }; (( failures == 0 )) && printf 'verify-overview: PASS\n' || exit "${HUAVD_EXIT_VERIFY}"
